#[path = "solution.rs"]
mod solution;

use solution::{build_transfers, check_capacity, Allocation, DistributionError};

fn allocation(recipient: &str, units: u64) -> Allocation {
    Allocation { recipient: recipient.to_string(), units }
}

#[test]
fn builds_transfers_in_order_and_keeps_duplicates() {
    let allocations = vec![allocation("alice", 3), allocation("bob", 7), allocation("alice", 2)];
    let transfers = build_transfers(&allocations).expect("valid allocations");

    assert_eq!(transfers.len(), 3);
    assert_eq!(transfers[0].recipient, "alice");
    assert_eq!(transfers[0].units, 3);
    assert_eq!(transfers[1].recipient, "bob");
    assert_eq!(transfers[1].units, 7);
    assert_eq!(transfers[2].recipient, "alice");
    assert_eq!(transfers[2].units, 2);

    assert_eq!(allocations[0].recipient, "alice");
    assert_eq!(allocations[0].units, 3);
    assert_eq!(allocations[2].recipient, "alice");
}

#[test]
fn build_transfers_accepts_empty_input_and_rejects_invalid_allocations() {
    assert!(build_transfers(&[]).expect("empty input is valid").is_empty());

    assert!(matches!(
        build_transfers(&[allocation("", 1)]),
        Err(DistributionError::EmptyRecipient)
    ));
    assert!(matches!(
        build_transfers(&[allocation("valid", 0)]),
        Err(DistributionError::ZeroAllocation)
    ));
}

#[test]
fn capacity_accepts_exact_and_surplus_funding() {
    let allocations = [allocation("a", 4), allocation("b", 6)];
    assert!(check_capacity(10, 11, &allocations, 5, 2, 3).is_ok());
    assert!(check_capacity(20, 20, &allocations, 5, 2, 3).is_ok());
}

#[test]
fn capacity_reports_insufficient_credits_before_insufficient_fees() {
    let allocations = [allocation("a", 5)];
    assert!(matches!(
        check_capacity(4, 0, &allocations, 10, 0, 0),
        Err(DistributionError::InsufficientCredits)
    ));
    assert!(matches!(
        check_capacity(5, 9, &allocations, 10, 0, 0),
        Err(DistributionError::InsufficientFees)
    ));
}

#[test]
fn allocation_validation_has_highest_precedence() {
    let invalid = [allocation("", 0), allocation("ok", u64::MAX)];
    assert!(matches!(
        check_capacity(0, 0, &invalid, u64::MAX, 2, u64::MAX),
        Err(DistributionError::EmptyRecipient)
    ));

    let zero = [allocation("ok", 0)];
    assert!(matches!(
        check_capacity(0, 0, &zero, u64::MAX, 2, u64::MAX),
        Err(DistributionError::ZeroAllocation)
    ));
}

#[test]
fn checked_allocation_and_fee_arithmetic_reports_overflow() {
    let overflowing_sum = [allocation("a", u64::MAX), allocation("b", 1)];
    assert!(matches!(
        check_capacity(u64::MAX, u64::MAX, &overflowing_sum, 0, 0, 0),
        Err(DistributionError::ArithmeticOverflow)
    ));

    let valid = [allocation("a", 1)];
    assert!(matches!(
        check_capacity(0, u64::MAX, &valid, u64::MAX, 1, 1),
        Err(DistributionError::ArithmeticOverflow)
    ));
    assert!(matches!(
        check_capacity(0, u64::MAX, &valid, 0, u64::MAX, 2),
        Err(DistributionError::ArithmeticOverflow)
    ));
}

#[test]
fn empty_allocations_require_only_calculated_fees() {
    assert!(check_capacity(0, 7, &[], 1, 2, 3).is_ok());
    assert!(matches!(
        check_capacity(0, 6, &[], 1, 2, 3),
        Err(DistributionError::InsufficientFees)
    ));
}

